package com.yuanqi.app.photo.service;
import com.yuanqi.app.photo.entity.MediaAsset;import com.yuanqi.app.photo.mapper.MediaAssetMapper;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import java.io.IOException;import java.time.Clock;import java.time.LocalDateTime;import java.time.ZoneOffset;import java.util.List;import java.util.Map;
@Service public class MediaCleanupWorker{private final JdbcTemplate jdbc;private final MediaAssetMapper media;private final MediaStorage storage;private final Clock clock;public MediaCleanupWorker(JdbcTemplate j,MediaAssetMapper m,MediaStorage s,Clock c){jdbc=j;media=m;storage=s;clock=c;}@Scheduled(fixedDelayString="${app.media.cleanup-delay-ms:60000}")public void run(){List<Map<String,Object>>jobs=jdbc.queryForList("SELECT id,media_id,attempt_count,deadline_at FROM media_cleanup_job WHERE status IN ('PENDING','RETRY') AND next_attempt_at<=UTC_TIMESTAMP(6) ORDER BY id LIMIT 20");for(Map<String,Object>j:jobs)runOne(((Number)j.get("id")).longValue(),((Number)j.get("media_id")).longValue(),((Number)j.get("attempt_count")).intValue(),((java.sql.Timestamp)j.get("deadline_at")).toLocalDateTime());}private void runOne(long job,long mediaId,int attempts,LocalDateTime deadline){MediaAsset a=media.selectById(mediaId);if(a==null||media.isReferenced(mediaId)){jdbc.update("UPDATE media_cleanup_job SET status='DELETED',updated_at=? WHERE id=?",now(),job);return;}try{storage.delete(a.getOriginalStorageKey());storage.delete(a.getWebStorageKey());a.setStatus("DELETED");a.setOriginalStorageKey(null);a.setWebStorageKey(null);a.setUpdatedAt(now());a.setRowVersion(a.getRowVersion()+1);media.updateById(a);jdbc.update("UPDATE media_cleanup_job SET status='DELETED',attempt_count=?,updated_at=? WHERE id=?",attempts+1,now(),job);}catch(IOException e){boolean exhausted=!deadline.isAfter(now());jdbc.update("UPDATE media_cleanup_job SET status=?,attempt_count=?,next_attempt_at=?,last_error_category='IO',updated_at=? WHERE id=?",exhausted?"EXHAUSTED":"RETRY",attempts+1,now().plusMinutes(Math.min(60,1L<<Math.min(6,attempts))),now(),job);}}private LocalDateTime now(){return LocalDateTime.ofInstant(clock.instant(),ZoneOffset.UTC);}}
